// Both screens go through CMND_BRIGHT_FADE_ALL, a single screen through
// CMND_BRIGHT_FADE; either way the helper waits for the fade to end.
StartBrightFade <- function ( _screen, _bright, _frame )
{
	if (_screen == SCREEN_AB)
	{
		CMND_BRIGHT_FADE_ALL(_bright, _frame);
		while (CMND_IS_BRIGHT_FADE_ALL())
		{
			suspend();
		}
	}
	else
	{
		CMND_BRIGHT_FADE(_screen, _bright, _frame);
		while (CMND_IS_BRIGHT_FADE(_screen))
		{
			suspend();
		}
	}
};
